diff --git a/crates/zero3-providers/src/weixin_clawbot.rs b/crates/zero3-providers/src/weixin_clawbot.rs
--- a/crates/zero3-providers/src/weixin_clawbot.rs
+++ b/crates/zero3-providers/src/weixin_clawbot.rs
@@ -481,9 +481,19 @@ fn persist_credentials(path: &Path, credentials: &WeixinCredentials) -> anyhow::Result<()> {
         let mut file = std::fs::File::create(&temp).context("create temporary Weixin state")?;
         file.write_all(&bytes).context("write temporary Weixin state")?;
         file.sync_all().context("sync temporary Weixin state")?;
     }
-    std::fs::rename(&temp, path).context("atomically replace Weixin state")?;
+    match std::fs::rename(&temp, path) {
+        Ok(()) => {}
+        Err(error) if cfg!(windows) => {
+            if path.exists() {
+                std::fs::remove_file(path).context("replace existing Weixin state on Windows")?;
+            }
+            std::fs::rename(&temp, path)
+                .context("finish replacing Weixin state on Windows")?;
+        }
+        Err(error) => return Err(error).context("atomically replace Weixin state"),
+    }
     Ok(())
 }

diff --git a/apps/weixin/src/main.rs b/apps/weixin/src/main.rs
--- a/apps/weixin/src/main.rs
+++ b/apps/weixin/src/main.rs
@@ -274,6 +274,9 @@ fn render_reply(value: &Value) -> String {
     if let Some(text) = value.as_str() {
         return text.to_string();
     }
+    if let Some(summary) = value.get("summary").and_then(Value::as_str) {
+        return summary.to_string();
+    }
     if let Some(output) = value.get("output").and_then(Value::as_str) {
         return output.to_string();
     }
